-- =============================================================================
-- Migration V8: Create Booking tables and constraints (Module 3)
-- Tables: bookings, booking_routes, booking_items, booking_services,
--         booking_vouchers, booking_status_history
-- =============================================================================

-- 1. Bảng bookings
CREATE TABLE IF NOT EXISTS "bookings" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "booking_code" varchar(50) UNIQUE NOT NULL,
  "customer_id" bigint NOT NULL,
  "created_by" bigint,
  "total_amount" decimal(12,2) NOT NULL DEFAULT 0,
  "discount_amount" decimal(12,2) NOT NULL DEFAULT 0,
  "note" text,
  "status" varchar(50) NOT NULL DEFAULT 'PENDING_SURVEY',
  "desired_start_at" timestamp,
  "desired_end_at" timestamp,
  "contact_name" varchar(255),
  "contact_phone" varchar(20),
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_bookings_customer FOREIGN KEY ("customer_id") REFERENCES "customers" ("user_id") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT fk_bookings_created_by FOREIGN KEY ("created_by") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT chk_bookings_total_amount CHECK (total_amount >= 0),
  CONSTRAINT chk_bookings_discount_amount CHECK (discount_amount >= 0)
);

CREATE INDEX IF NOT EXISTS idx_bookings_customer_id ON "bookings" ("customer_id");
CREATE INDEX IF NOT EXISTS idx_bookings_status ON "bookings" ("status");
CREATE INDEX IF NOT EXISTS idx_bookings_customer_status ON "bookings" ("customer_id", "status");
CREATE INDEX IF NOT EXISTS idx_bookings_code ON "bookings" ("booking_code");

-- 2. Bảng booking_routes (1-1 với bookings)
CREATE TABLE IF NOT EXISTS "booking_routes" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "booking_id" int UNIQUE NOT NULL,
  "pickup_address" varchar(500) NOT NULL,
  "pickup_lat" decimal(10,7),
  "pickup_lng" decimal(10,7),
  "pickup_property_type" varchar(50),
  "pickup_note" text,
  "dropoff_address" varchar(500) NOT NULL,
  "dropoff_lat" decimal(10,7),
  "dropoff_lng" decimal(10,7),
  "dropoff_property_type" varchar(50),
  "dropoff_note" text,
  "estimated_distance_km" decimal(10,2),
  CONSTRAINT fk_booking_routes_booking FOREIGN KEY ("booking_id") REFERENCES "bookings" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE
);

CREATE INDEX IF NOT EXISTS idx_booking_routes_booking_id ON "booking_routes" ("booking_id");

-- 3. Bảng booking_items (Danh mục đồ đạc)
CREATE TABLE IF NOT EXISTS "booking_items" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "booking_id" int NOT NULL,
  "item_name" varchar(255) NOT NULL,
  "quantity" int NOT NULL DEFAULT 1,
  "estimated_volume_m3" decimal(10,2),
  "is_fragile" boolean NOT NULL DEFAULT false,
  "packing_required" boolean NOT NULL DEFAULT false,
  "disassembly_required" boolean NOT NULL DEFAULT false,
  "note" text,
  CONSTRAINT fk_booking_items_booking FOREIGN KEY ("booking_id") REFERENCES "bookings" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT chk_booking_items_quantity CHECK (quantity > 0)
);

CREATE INDEX IF NOT EXISTS idx_booking_items_booking_id ON "booking_items" ("booking_id");

-- 4. Bảng booking_services (Dịch vụ chọn kèm Snapshot đơn giá)
CREATE TABLE IF NOT EXISTS "booking_services" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "booking_id" int NOT NULL,
  "service_id" int NOT NULL,
  "price_applied" decimal(12,2) NOT NULL,
  "quantity" int NOT NULL DEFAULT 1,
  "note" text,
  CONSTRAINT fk_booking_services_booking FOREIGN KEY ("booking_id") REFERENCES "bookings" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT fk_booking_services_service FOREIGN KEY ("service_id") REFERENCES "services" ("id") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT chk_booking_services_price_applied CHECK (price_applied >= 0),
  CONSTRAINT chk_booking_services_quantity CHECK (quantity > 0)
);

CREATE INDEX IF NOT EXISTS idx_booking_services_booking_id ON "booking_services" ("booking_id");
CREATE INDEX IF NOT EXISTS idx_booking_services_service_id ON "booking_services" ("service_id");

-- 5. Bảng booking_vouchers (Voucher áp dụng cho đơn)
CREATE TABLE IF NOT EXISTS "booking_vouchers" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "voucher_id" int NOT NULL,
  "booking_id" int NOT NULL,
  "discount_amount" decimal(12,2) NOT NULL,
  "applied_date" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_booking_vouchers_voucher FOREIGN KEY ("voucher_id") REFERENCES "vouchers" ("id") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT fk_booking_vouchers_booking FOREIGN KEY ("booking_id") REFERENCES "bookings" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT chk_booking_vouchers_discount_amount CHECK (discount_amount >= 0)
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_booking_vouchers_unique ON "booking_vouchers" ("voucher_id", "booking_id");
CREATE INDEX IF NOT EXISTS idx_booking_vouchers_voucher_id ON "booking_vouchers" ("voucher_id");
CREATE INDEX IF NOT EXISTS idx_booking_vouchers_booking_id ON "booking_vouchers" ("booking_id");

-- 6. Bảng booking_status_history (Nhật ký trạng thái)
CREATE TABLE IF NOT EXISTS "booking_status_history" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "booking_id" int NOT NULL,
  "old_status" varchar(50),
  "new_status" varchar(50) NOT NULL,
  "changed_by" bigint,
  "changed_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "note" text,
  CONSTRAINT fk_booking_status_history_booking FOREIGN KEY ("booking_id") REFERENCES "bookings" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT fk_booking_status_history_changed_by FOREIGN KEY ("changed_by") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE
);

CREATE INDEX IF NOT EXISTS idx_booking_status_history_booking_id ON "booking_status_history" ("booking_id");
CREATE INDEX IF NOT EXISTS idx_booking_status_history_changed_at ON "booking_status_history" ("booking_id", "changed_at");

